<?php
declare(strict_types=1);
define('ROOT',dirname(__DIR__));
foreach(file(ROOT.'/.env',FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES)?:[] as $line){$line=trim($line);if($line===''||$line[0]==='#'||!str_contains($line,'='))continue;[$k,$v]=explode('=',$line,2);$_ENV[trim($k)]=trim(trim($v),\" \\\"'\");}
date_default_timezone_set('Asia/Dhaka');session_name('shop_session');session_set_cookie_params(['httponly'=>true,'secure'=>!empty($_SERVER['HTTPS']),'samesite'=>'Lax']);if(session_status()!==PHP_SESSION_ACTIVE)session_start();
function db():PDO{static $pdo;if(!$pdo){$pdo=new PDO('mysql:host='.($_ENV['DB_HOST']??'127.0.0.1').';port='.($_ENV['DB_PORT']??'3306').';dbname='.($_ENV['DB_DATABASE']??'ecommerce').';charset=utf8mb4',$_ENV['DB_USERNAME']??'root',$_ENV['DB_PASSWORD']??'', [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);}return $pdo;}
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function money($v):string{return '৳'.number_format((float)$v,2);}function csrf():string{return $_SESSION['_csrf']??=bin2hex(random_bytes(32));}function csrf_input():string{return '<input type=\"hidden\" name=\"_csrf\" value=\"'.e(csrf()).'\">';}function check_csrf():void{if($_SERVER['REQUEST_METHOD']==='POST'&&!hash_equals($_SESSION['_csrf']??'',$_POST['_csrf']??'')){http_response_code(419);exit('Invalid session token');}}function go($p=''):never{header('Location: '.rtrim($_ENV['APP_URL']??'','/').'/'.$p);exit;}function msg($v=null){if($v!==null){$_SESSION['_msg']=$v;return;} $m=$_SESSION['_msg']??null;unset($_SESSION['_msg']);return $m;}
function user(){return $_SESSION['user']??null;}function login_required():void{if(!user())go('login');}function admin_required():void{login_required();if(user()['role']!=='admin'){http_response_code(403);exit('Forbidden');}}
function products($q=''):array{$sql='SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.is_active=1';$a=[];if($q!==''){$sql.=' AND p.name LIKE ?';$a[]='%'.$q.'%';}$s=db()->prepare($sql.' ORDER BY p.id DESC LIMIT 80');$s->execute($a);return $s->fetchAll();}
